export function generateHiragana(yinjie, tone, withoutAccent = false) {
  if (typeof yinjie !== "string") {
    throw new Error("参数类型错误！必须是字符串。");
  }
  yinjie = yinjie.replace(/ü/g, "v").replace(/u:/g, "v");
  const gana = YINJIE[yinjie];
  if (!gana) return "";

  if (withoutAccent) {
    return `${gana[0]}${gana[1]}`;
  }

  if (tone.length !== 3) {
    throw new Error(`声调必须是3位数字组成的字符串: ${tone}.`);
  }

  const lastTone = tone[0];
  const thisTone = tone[1];
  const nextTone = tone[2];

  if (
    !"012345".includes(lastTone) ||
    !"12345".includes(thisTone) ||
    !"012345".includes(nextTone)
  ) {
    throw new Error(`声调格式错误: ${tone}.`);
  }

  const base = `${gana[0]}${gana[1]}`;

  if (thisTone === "1" || thisTone === "5") {
    if (thisTone === "5") {
      return lastTone === "0" ? `/っ${gana[0]}` : gana[0];
    }
    if (lastTone === "0") {
      return `/っ${base}`;
    }
    return base;
  }

  if (thisTone === "2") {
    return `/${base}`;
  }

  if (thisTone === "3") {
    if (lastTone === "4") {
      if (nextTone === "0" || nextTone === "3") {
        return base;
      }
      return `${gana[0]}/${gana[1]}`;
    }
    if (nextTone === "3") {
      return `'${base}`;
    }
    return `'${gana[0]}/${gana[1]}`;
  }

  if (nextTone === "0" || nextTone === "2" || nextTone === "3") {
    return `${gana[0]}'${gana[1]}`;
  }
  if (lastTone === "0") {
    return `${gana[0]}'/${gana[1]}`;
  }
  return `${gana[0]}/${gana[1]}`;
}

export function generateValidNumbers() {
  const digits = ["0", "1", "2", "3", "4", "5"];
  const middleDigits = ["1", "2", "3", "4", "5"];
  const result = [];
  for (const d1 of digits) {
    for (const d2 of middleDigits) {
      for (const d3 of digits) {
        result.push(`${d1}${d2}${d3}`);
      }
    }
  }
  return result;
}
